          citations.add(`outcome:${k2}@v${o?.version ?? 1}`);
          lines.push(`- \`${k2}\` **${o?.title ?? k2}** \u2014 \`${r2?.signal ?? "unverified"}\`${r2?.blockedBy.length ? ` (blocked by ${r2.blockedBy.join(", ")})` : ""}`);
