        const why = b2.signal === "broken" ? "broken (failing evidence)" : b2.availability === "blocked" ? `blocked: ${b2.availabilityReason ?? "external"}` : `waiting on ${b2.blockedBy.join(", ")}`;
        lines.push(`- \`${b2.key}\` **${o?.title ?? b2.key}** \u2014 ${why}`);
